<style>
  :root {
    --blue: #3861FB;
    --navy: #0D1421;
    --gray: #808A9D;
    --gray-light: #EFF2F5;
    --gray-border: #CFD6E4;
    --white: #FFFFFF;
    --green: #16c784;
    --red: #ea3943;
    --bg: #FFFFFF;
    --text: #0D1421;
    --text-secondary: #808A9D;
    --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html { font-size: 14px; -webkit-font-smoothing: antialiased; }

  body {
    font-family: var(--font);
    background: var(--bg);
    color: var(--text);
    line-height: 1.5;
    min-height: 100vh;
  }

  a { color: var(--blue); text-decoration: none; }
  a:hover { text-decoration: underline; }

  /* Utility */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 16px; }
  .text-right { text-align: right; }
  .text-green { color: var(--green); }
  .text-red { color: var(--red); }
  .text-gray { color: var(--text-secondary); }
  .font-mono { font-variant-numeric: tabular-nums; font-feature-settings: 'tnum'; }

  /* ===== HEADER / NAV ===== */
  .header {
    background: var(--white);
    border-bottom: 1px solid var(--gray-border);
    position: sticky;
    top: 0;
    z-index: 100;
  }
  .header-inner {
    display: flex;
    align-items: center;
    height: 56px;
    gap: 24px;
  }
  .logo {
    font-weight: 700;
    font-size: 18px;
    color: var(--navy);
    white-space: nowrap;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .logo-icon {
    width: 28px;
    height: 28px;
    background: var(--blue);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 14px;
    font-weight: 700;
  }
  .nav { display: flex; gap: 4px; flex: 1; }
  .nav-item {
    padding: 6px 12px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text);
    border-radius: 6px;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
  }
  .nav-item:hover { background: var(--gray-light); }
  .header-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
  .btn-login {
    padding: 6px 16px;
    font-size: 13px;
    font-weight: 600;
    color: var(--blue);
    border: 1px solid var(--blue);
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    transition: all 0.15s;
  }
  .btn-login:hover { background: rgba(56,97,251,0.06); }
  .btn-signup {
    padding: 6px 16px;
    font-size: 13px;
    font-weight: 600;
    color: white;
    background: var(--blue);
    border: 1px solid var(--blue);
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s;
  }
  .btn-signup:hover { background: #2a4fd8; }

  /* ===== TOP BAR METRICS ===== */
  .metrics-bar {
    background: var(--gray-light);
    border-bottom: 1px solid var(--gray-border);
    padding: 8px 0;
  }
  .metrics-inner {
    display: flex;
    align-items: center;
    gap: 24px;
    overflow-x: auto;
  }
  .metric {
    display: flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    font-size: 13px;
  }
  .metric-label { color: var(--text-secondary); }
  .metric-value { font-weight: 600; font-variant-numeric: tabular-nums; }
  .metric-change { font-size: 12px; font-weight: 500; }
  .metric-sep { width: 1px; height: 20px; background: var(--gray-border); flex-shrink: 0; }

  /* ===== PROMO BANNER ===== */
  .promo-banner {
    background: linear-gradient(90deg, #1a1f36, #252b48);
    color: white;
    padding: 14px 0;
    overflow: hidden;
    position: relative;
  }
  .promo-carousel {
    display: flex;
    transition: transform 0.5s ease;
  }
  .promo-slide {
    min-width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-size: 14px;
  }
  .promo-slide strong { font-weight: 600; }
  .promo-cta {
    padding: 5px 14px;
    background: var(--blue);
    border-radius: 4px;
    font-size: 12px;
    font-weight: 600;
    color: white;
    cursor: pointer;
    transition: background 0.15s;
  }
  .promo-cta:hover { background: #2a4fd8; text-decoration: none; }
  .promo-arrows {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 100%;
    display: flex;
    justify-content: space-between;
    padding: 0 12px;
    pointer-events: none;
  }
  .promo-arrow {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: rgba(255,255,255,0.15);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    pointer-events: auto;
    font-size: 14px;
    color: white;
    border: none;
    transition: background 0.15s;
  }
  .promo-arrow:hover { background: rgba(255,255,255,0.25); }
  .promo-dots {
    display: flex;
    justify-content: center;
    gap: 6px;
    margin-top: 8px;
  }
  .promo-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255,255,255,0.3);
    cursor: pointer;
    transition: background 0.15s;
  }
  .promo-dot.active { background: white; }

  /* ===== AI ALERTS BAR ===== */
  .ai-bar {
    background: var(--white);
    border-bottom: 1px solid var(--gray-border);
    padding: 10px 0;
  }
  .ai-bar-inner {
    display: flex;
    align-items: center;
    gap: 12px;
    overflow-x: auto;
  }
  .ai-prompt {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 500;
    color: var(--navy);
    white-space: nowrap;
  }
  .ai-badge {
    background: linear-gradient(135deg, #3861FB, #8B5CF6);
    color: white;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 4px;
  }
  .ai-chip {
    padding: 5px 12px;
    background: var(--gray-light);
    border-radius: 20px;
    font-size: 12px;
    color: var(--text-secondary);
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.15s;
    border: 1px solid transparent;
  }
  .ai-chip:hover { border-color: var(--blue); color: var(--blue); }

  /* ===== NETWORK FILTER TABS ===== */
  .network-tabs {
    padding: 12px 0 0;
    border-bottom: 1px solid var(--gray-border);
  }
  .network-tabs-inner {
    display: flex;
    align-items: center;
    gap: 0;
    overflow-x: auto;
  }
  .network-tab {
    padding: 8px 16px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    border-bottom: 2px solid transparent;
    white-space: nowrap;
    transition: all 0.15s;
  }
  .network-tab:hover { color: var(--text); }
  .network-tab.active {
    color: var(--blue);
    border-bottom-color: var(--blue);
    font-weight: 600;
  }

  /* ===== CATEGORY TABS ===== */
  .category-tabs {
    padding: 12px 0 0;
  }
  .category-tabs-inner {
    display: flex;
    align-items: center;
    gap: 0;
    overflow-x: auto;
  }
  .category-tab {
    padding: 8px 16px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    border-bottom: 2px solid transparent;
    white-space: nowrap;
    transition: all 0.15s;
    background: none;
    border-top: none;
    border-left: none;
    border-right: none;
  }
  .category-tab:hover { color: var(--text); }
  .category-tab.active {
    color: var(--blue);
    border-bottom-color: var(--blue);
    font-weight: 600;
  }

  /* ===== TABLE CONTROLS ===== */
  .table-controls {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px 0 8px;
  }
  .control-btn {
    padding: 5px 12px;
    font-size: 12px;
    font-weight: 500;
    color: var(--text-secondary);
    background: var(--white);
    border: 1px solid var(--gray-border);
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
    transition: all 0.15s;
  }
  .control-btn:hover { border-color: var(--blue); color: var(--blue); }
  .control-btn.active { background: var(--blue); color: white; border-color: var(--blue); }
  .control-btn .arrow { font-size: 10px; }

  /* ===== FILTER PANEL ===== */
  .filter-panel {
    display: none;
    padding: 16px;
    background: var(--gray-light);
    border: 1px solid var(--gray-border);
    border-radius: 8px;
    margin-bottom: 12px;
  }
  .filter-panel.open { display: block; }
  .filter-row {
    display: flex;
    gap: 16px;
    align-items: center;
    margin-bottom: 12px;
  }
  .filter-row:last-child { margin-bottom: 0; }
  .filter-label { font-size: 12px; font-weight: 600; color: var(--text-secondary); min-width: 80px; }
  .filter-input {
    padding: 6px 10px;
    font-size: 13px;
    border: 1px solid var(--gray-border);
    border-radius: 4px;
    font-family: var(--font);
    width: 140px;
  }
  .filter-input:focus { outline: none; border-color: var(--blue); }

  /* ===== COLUMNS PANEL ===== */
  .columns-panel {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    z-index: 50;
    background: var(--white);
    border: 1px solid var(--gray-border);
    border-radius: 8px;
    padding: 12px;
    box-shadow: 0 4px 16px rgba(0,0,0,0.1);
    min-width: 200px;
  }
  .columns-panel.open { display: block; }
  .columns-panel label {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 0;
    font-size: 13px;
    cursor: pointer;
  }
  .columns-panel input[type="checkbox"] { accent-color: var(--blue); }

  /* ===== CRYPTO TABLE ===== */
  .table-wrap {
    overflow-x: auto;
    position: relative;
  }
  .crypto-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }
  .crypto-table th {
    padding: 8px 10px;
    font-size: 11px;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    border-bottom: 1px solid var(--gray-border);
    background: var(--white);
    white-space: nowrap;
    position: sticky;
    top: 56px;
    z-index: 10;
    cursor: pointer;
    user-select: none;
  }
  .crypto-table th:hover { color: var(--navy); }
  .crypto-table th.sort-asc::after { content: ' ▲'; font-size: 9px; }
  .crypto-table th.sort-desc::after { content: ' ▼'; font-size: 9px; }
  .crypto-table td {
    padding: 10px 10px;
    border-bottom: 1px solid #f0f2f5;
    white-space: nowrap;
  }
  .crypto-table tbody tr {
    transition: background 0.1s;
  }
  .crypto-table tbody tr:hover {
    background: #f8f9fb;
  }

  /* Name cell */
  .coin-name {
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .coin-icon {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 10px;
    color: white;
    flex-shrink: 0;
  }
  .coin-info { display: flex; flex-direction: column; }
  .coin-symbol { font-weight: 600; color: var(--navy); font-size: 13px; }
  .coin-fullname { font-size: 11px; color: var(--text-secondary); }

  /* Sparkline */
  .sparkline { width: 100px; height: 32px; }
  .sparkline svg { width: 100%; height: 100%; }

  /* Star button */
  .star-btn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--gray-border);
    font-size: 14px;
    padding: 2px;
    transition: color 0.15s;
  }
  .star-btn:hover, .star-btn.active { color: #f5a623; }

  /* Index row */
  .index-row {
    background: #f0f4ff;
  }
  .index-row td {
    border-bottom: 2px solid var(--gray-border);
    font-weight: 500;
  }

  /* ===== PAGINATION ===== */
  .pagination {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 20px 0;
  }
  .page-btn {
    min-width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 500;
    border: 1px solid var(--gray-border);
    border-radius: 6px;
    background: var(--white);
    color: var(--text);
    cursor: pointer;
    transition: all 0.15s;
  }
  .page-btn:hover { border-color: var(--blue); color: var(--blue); }
  .page-btn.active { background: var(--blue); color: white; border-color: var(--blue); }
  .page-ellipsis { padding: 0 8px; color: var(--text-secondary); }
  .pagination-info {
    text-align: center;
    font-size: 12px;
    color: var(--text-secondary);
    padding-bottom: 16px;
  }

  /* ===== MARKET SUMMARY ===== */
  .market-summary {
    padding: 32px 0;
    border-top: 1px solid var(--gray-border);
  }
  .market-summary h2 { font-size: 18px; font-weight: 600; margin-bottom: 12px; }
  .market-summary p { font-size: 14px; line-height: 1.7; color: #3a3f50; }
  .market-summary strong { color: var(--navy); }
  .read-more-btn {
    display: inline-block;
    margin-top: 8px;
    font-size: 13px;
    font-weight: 600;
    color: var(--blue);
    cursor: pointer;
    background: none;
    border: none;
    padding: 0;
  }
  .read-more-btn:hover { text-decoration: underline; }
  .market-summary-extra { display: none; margin-top: 8px; }
  .market-summary-extra.open { display: block; }

  /* ===== INFO CONTENT ===== */
  .info-content {
    padding: 32px 0;
    border-top: 1px solid var(--gray-border);
  }
  .info-content h2 { font-size: 18px; font-weight: 600; margin-bottom: 12px; }
  .info-content h3 { font-size: 15px; font-weight: 600; margin: 20px 0 8px; color: var(--navy); }
  .info-content p { font-size: 14px; line-height: 1.7; color: #3a3f50; }

  /* ===== FOOTER ===== */
  .footer {
    background: #0D1421;
    color: #9eaab8;
    padding: 40px 0 24px;
  }
  .footer-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 32px;
    margin-bottom: 32px;
  }
  .footer-col h4 {
    color: white;
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .footer-col a {
    display: block;
    font-size: 13px;
    color: #9eaab8;
    padding: 3px 0;
    transition: color 0.15s;
  }
  .footer-col a:hover { color: white; text-decoration: none; }
  .footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.1);
    padding-top: 20px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-social { display: flex; gap: 12px; }
  .footer-social a { color: #9eaab8; font-size: 16px; }
  .footer-social a:hover { color: white; text-decoration: none; }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .nav { display: none; }
    .metrics-inner { gap: 12px; }
    .footer-grid { grid-template-columns: repeat(2, 1fr); }
    .crypto-table { font-size: 12px; }
  }

  /* Scrollbar */
  ::-webkit-scrollbar { height: 6px; width: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--gray-border); border-radius: 3px; }
</style>
</head>
<body>

<!-- ===== HEADER ===== -->
<header class="header">
  <div class="container header-inner">
    <div class="logo">
      <div class="logo-icon">CT</div>
      CoinTracker Pro
    </div>
    <nav class="nav">
      <div class="nav-item" onclick="location.href='index.html'">Cryptocurrencies</div>
      <div class="nav-item" onclick="location.href='index.html'">Dashboards</div>
      <div class="nav-item" onclick="location.href='index.html'">Exchanges</div>
      <div class="nav-item" onclick="location.href='index.html'">DexScan</div>
    </nav>
    <div class="header-actions">
      <button class="btn-login">Log In</button>
      <button class="btn-signup">Sign Up</button>
    </div>
  </div>
</header>

<!-- ===== TOP BAR METRICS ===== -->
<section class="metrics-bar">
  <div class="container">
    <div class="metrics-inner">
      <div class="metric">
        <span class="metric-label">Cryptos:</span>
        <span class="metric-value">8,364</span>
      </div>
      <div class="metric-sep"></div>
      <div class="metric">
        <span class="metric-label">Market Cap:</span>
        <span class="metric-value">$2.56T</span>
        <span class="metric-change text-green">↑ 1.46%</span>
      </div>
      <div class="metric-sep"></div>
      <div class="metric">
        <span class="metric-label">CTP20 Index:</span>
        <span class="metric-value">$155.36</span>
        <span class="metric-change text-green">↑ 1.5%</span>
      </div>
      <div class="metric-sep"></div>
      <div class="metric">
        <span class="metric-label">Fear &amp; Greed:</span>
        <span class="metric-value">57</span>
        <span class="metric-change" style="color:#c8a415;">Neutral</span>
      </div>
      <div class="metric-sep"></div>
      <div class="metric">
        <span class="metric-label">Altcoin Season:</span>
        <span class="metric-value">37/100</span>
        <span class="metric-change text-gray">Bitcoin season</span>
      </div>
    </div>
  </div>
</section>

