// ========== FORMATTING ==========
function fmtPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toFixed(2);
  if (p >= 0.01) return '$' + p.toFixed(4);
  if (p >= 0.0001) return '$' + p.toFixed(6);
  if (p >= 0.00000001) return '$' + p.toFixed(8);
  return '$' + p.toFixed(11);
}

function fmtMcap(v) {
  if (v >= 1e12) return '$' + (v/1e12).toFixed(2) + 'T';
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}

function fmtVol(v) {
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}

function fmtSupply(v, sym) {
  if (v >= 1e12) return (v/1e12).toFixed(2) + 'T ' + sym;
  if (v >= 1e9) return (v/1e9).toFixed(2) + 'B ' + sym;
  if (v >= 1e6) return (v/1e6).toFixed(2) + 'M ' + sym;
  return v.toLocaleString() + ' ' + sym;
}

function fmtPct(v) {
  const sign = v >= 0 ? '+' : '';
  return sign + v.toFixed(2) + '%';
}

function pctClass(v) {
  return v >= 0 ? 'text-green' : 'text-red';
}

// ========== SPARKLINE SVG ==========
function sparklineSVG(data, isPositive) {
  const w = 100, h = 32, pad = 2;
  const min = Math.min(...data), max = Math.max(...data);
  const range = max - min || 1;
  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * (w - 2 * pad);
    const y = h - pad - ((v - min) / range) * (h - 2 * pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const color = isPositive ? '#16c784' : '#ea3943';
  return `<svg viewBox="0 0 ${w} ${h}" fill="none" xmlns="http://www.w3.org/2000/svg">
    <polyline points="${points}" stroke="${color}" stroke-width="1.5" fill="none"/>
  </svg>`;
}

// ========== RENDER TABLE ==========
let currentData = [...CRYPTO_DATA];
let currentCategory = 'top';
let currentNetwork = 'all';
let sortKey = 'mcap';
let sortDir = -1; // -1 = desc

function getFilteredData() {
  let data = [...CRYPTO_DATA];

  // Category filter
  if (currentCategory === 'trending') data = data.filter(c => c.cat === 'trending' || TRENDING_IDS.includes(c.r));
  else if (currentCategory === 'watchlist') data = data.filter(c => c.wl);
  else if (currentCategory === 'prediction') data = data.filter(c => c.pred);
  else if (currentCategory === 'visited') data = data.filter(c => c.vis);
  else if (currentCategory === 'new') data = data.filter(c => c.newc);
  // 'top' shows all

  // Network filter
  if (currentNetwork !== 'all' && currentNetwork !== 'more') {
    data = data.filter(c => c.net === currentNetwork);
  }

  // Sort
  data.sort((a, b) => {
    let va, vb;
    switch(sortKey) {
      case 'mcap': va = a.mcap; vb = b.mcap; break;
      case 'vol': va = a.vol; vb = b.vol; break;
      case 'price': va = a.price; vb = b.price; break;
      case 'h1': va = a.h1; vb = b.h1; break;
      case 'h24': va = a.h24; vb = b.h24; break;
      case 'd7': va = a.d7; vb = b.d7; break;
      default: va = a.mcap; vb = b.mcap;
    }
    return (vb - va) * sortDir;
  });

  return data;
}

function renderTable() {
  const data = getFilteredData();
  const tbody = document.getElementById('cryptoBody');
  let html = '';

  // Index row
  html += `<tr class="index-row">
    <td></td>
    <td><div class="coin-name"><div class="coin-icon" style="background:var(--blue);">20</div><div class="coin-info"><span class="coin-symbol">CoinTracker 20 Index</span><span class="coin-fullname">DTFCTP20</span></div></div></td>
    <td class="text-right font-mono">$154.29</td>
    <td class="text-right font-mono text-green">+0.21%</td>
    <td class="text-right font-mono text-green">+1.15%</td>
    <td class="text-right font-mono text-green">+4.97%</td>
    <td class="text-right font-mono">—</td>
    <td class="text-right font-mono">—</td>
    <td class="text-right font-mono">—</td>
    <td class="text-right"><div class="sparkline">${sparklineSVG([0.98,0.99,1.00,1.00,1.01,1.02,1.05], true)}</div></td>
  </tr>`;

  data.forEach((c, i) => {
    const color = COIN_COLORS[c.sym] || '#3861FB';
    const initials = c.sym.slice(0, 2);
    html += `<tr>
      <td class="text-right font-mono">${c.r}</td>
      <td><div class="coin-name">
        <button class="star-btn" onclick="this.classList.toggle('active')">☆</button>
        <div class="coin-icon" style="background:${color};">${initials}</div>
        <div class="coin-info"><span class="coin-symbol">${c.sym}</span><span class="coin-fullname">${c.name}</span></div>
      </div></td>
      <td class="text-right font-mono">${fmtPrice(c.price)}</td>
      <td class="text-right font-mono ${pctClass(c.h1)}">${fmtPct(c.h1)}</td>
      <td class="text-right font-mono ${pctClass(c.h24)}">${fmtPct(c.h24)}</td>
      <td class="text-right font-mono ${pctClass(c.d7)}">${fmtPct(c.d7)}</td>
      <td class="text-right font-mono">${fmtMcap(c.mcap)}</td>
      <td class="text-right font-mono">${fmtVol(c.vol)}</td>
      <td class="text-right font-mono">${fmtSupply(c.sup, c.supSym)}</td>
      <td class="text-right"><div class="sparkline">${sparklineSVG(c.spark, c.d7 >= 0)}</div></td>
    </tr>`;
  });

  tbody.innerHTML = html;

  // Update pagination info
  const info = document.querySelector('.pagination-info');
  if (data.length === 0) {
    info.textContent = 'No assets found matching your criteria';
  } else {
    info.textContent = `Showing 1–${data.length} of ${data.length === CRYPTO_DATA.length ? '8,364' : data.length} assets`;
  }
}

// ========== INTERACTIONS ==========

// Category tabs
document.getElementById('categoryTabs').addEventListener('click', (e) => {
  const tab = e.target.closest('.category-tab');
  if (!tab) return;
  document.querySelectorAll('.category-tab').forEach(t => t.classList.remove('active'));
  tab.classList.add('active');
  currentCategory = tab.dataset.cat;
  renderTable();
});

// Network filter tabs
document.getElementById('networkTabs').addEventListener('click', (e) => {
