});

// Table header sorting
document.querySelectorAll('.crypto-table th').forEach(th => {
  th.addEventListener('click', () => {
    const col = th.dataset.col;
    const keyMap = {rank:'r', name:'name', price:'price', '1h':'h1', '24h':'h24', '7d':'d7', mcap:'mcap', vol:'vol', supply:'sup', spark:null};
    if (col === 'name' || col === 'spark' || !keyMap[col]) return;
    if (sortKey === keyMap[col]) sortDir *= -1;
    else { sortKey = keyMap[col]; sortDir = -1; }
    document.querySelectorAll('.crypto-table th').forEach(t => t.classList.remove('sort-asc','sort-desc'));
    th.classList.add(sortDir === 1 ? 'sort-asc' : 'sort-desc');
