  document.getElementById('columnsPanel').classList.remove('open');
});

function applyFilters() {
  const mcapMin = parseFloat(document.getElementById('filterMcapMin').value) || 0;
  const mcapMax = parseFloat(document.getElementById('filterMcapMax').value) || Infinity;
  const priceMin = parseFloat(document.getElementById('filterPriceMin').value) || 0;
  const priceMax = parseFloat(document.getElementById('filterPriceMax').value) || Infinity;
  const h24Min = parseFloat(document.getElementById('filter24hMin').value) || -Infinity;
  const h24Max = parseFloat(document.getElementById('filter24hMax').value) || Infinity;

  // Convert mcap filter from billions if user enters in B
  currentData = CRYPTO_DATA.filter(c => {
    return c.mcap >= mcapMin * 1e9 && c.mcap <= mcapMax * 1e9 &&
           c.price >= priceMin && c.price <= priceMax &&
           c.h24 >= h24Min && c.h24 <= h24Max;
  });

  // Temporarily override CRYPTO_DATA for rendering
  const origData = [...CRYPTO_DATA];
  CRYPTO_DATA.length = 0;
  CRYPTO_DATA.push(...currentData);
  renderTable();
  CRYPTO_DATA.length = 0;
  CRYPTO_DATA.push(...origData);
}

function resetFilters() {
  document.getElementById('filterMcapMin').value = '';
  document.getElementById('filterMcapMax').value = '';
  document.getElementById('filterPriceMin').value = '';
  document.getElementById('filterPriceMax').value = '';
  document.getElementById('filter24hMin').value = '';
  document.getElementById('filter24hMax').value = '';
