let promoSlide = 0;
const totalSlides = 3;

function slidePromo(dir) {
  promoSlide = (promoSlide + dir + totalSlides) % totalSlides;
  updatePromo();
}

function goToSlide(n) {
  promoSlide = n;
  updatePromo();
}

function updatePromo() {
  document.getElementById('promoCarousel').style.transform = `translateX(-${promoSlide * 100}%)`;
  document.querySelectorAll('.promo-dot').forEach((d, i) => {
    d.classList.toggle('active', i === promoSlide);
  });
