arguments.content:
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const page = await context.newPage();

  const results = [];
  const log = (step, pass, detail) => {
    const icon = pass ? '✅' : '❌';
    results.push({ step, pass, detail });
    console.log(`${icon} ${step}: ${detail}`);
  };

  await page.goto('http://localhost:8080/', { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForTimeout(1000);

  // 1. Top bar metrics
  console.log('\n=== TOP BAR METRICS ===');
  const metricsBar = await page.textContent('.metrics-bar');
  log('Market Cap $2.56T', metricsBar.includes('$2.56T'), `Found`);
  log('CTP20 Index $155.36', metricsBar.includes('$155.36'), `Found`);
  log('Fear & Greed 57', metricsBar.includes('57'), `Found`);
  log('Neutral label', metricsBar.includes('Neutral'), `Found`);
  log('Altcoin Season 37/100', metricsBar.includes('37/100'), `Found`);
  log('1.46% change', metricsBar.includes('1.46%'), `Found`);

  // 2. Promo banner
  console.log('\n=== PROMO BANNER ===');
  const promoText = await page.textContent('.promo-banner');
  log('Promo banner exists', promoText.length > 0, `Content length: ${promoText.length}`);
  log('$GENIUS Airdrop', promoText.includes('GENIUS'), `Found`);
  log('Join Now CTA', promoText.includes('Join Now'), `Found`);
  // Carousel auto-rotation
  await page.waitForTimeout(5500);
  const carouselTransform = await page.evaluate(() => document.getElementById('promoCarousel').style.transform);
  log('Carousel auto-rotates', carouselTransform.includes('translateX'), `Transform: "${carouselTransform}"`);

  // 3. AI alerts bar
  console.log('\n=== AI ALERTS BAR ===');
  const aiBar = await page.textContent('.ai-bar');
  log('AI badge', aiBar.includes('AI'), `Found`);
  log('Stablecoin/Solana prompt', aiBar.includes('Solana DeFi'), `Found`);
  log('All 7 chips present',
    aiBar.includes('market up') && aiBar.includes('altcoins') && aiBar.includes('trending narratives') &&
    aiBar.includes('bullish momentum') && aiBar.includes('upcoming events') && aiBar.includes('market sentiment') && aiBar.includes('KOLs'),
    `Found all chips`);

  // 4. Network filter tabs
  console.log('\n=== NETWORK FILTER TABS ===');
  const networkTabs = await page.$$eval('.network-tab', els => els.map(e => e.textContent.trim()));
  log('All network tabs present',
    networkTabs.includes('All Networks') && networkTabs.includes('BSC') && networkTabs.includes('Solana') &&
    networkTabs.includes('Base') && networkTabs.includes('Ethereum'),
    `Tabs: ${networkTabs.join(', ')}`);

  const initialRowCount = await page.$$eval('#cryptoBody tr', rows => rows.length);
  await page.click('.network-tab[data-network="solana"]');
  await page.waitForTimeout(300);
  const solanaRowCount = await page.$$eval('#cryptoBody tr', rows => rows.length);
  log('Solana filter reduces rows', solanaRowCount < initialRowCount,
    `All: ${initialRowCount}, Solana: ${solanaRowCount}`);

  await page.click('.network-tab[data-network="all"]');
  await page.waitForTimeout(300);
  const restoredRowCount = await page.$$eval('#cryptoBody tr', rows => rows.length);
  log('All Networks restores rows', restoredRowCount === initialRowCount, `Restored: ${restoredRowCount}`);

  // 5. Category tabs
  console.log('\n=== CATEGORY TABS ===');
  const categoryTabs = await page.$$eval('.category-tab', els => els.map(e => e.textContent.trim()));
  log('All category tabs present',
    categoryTabs.includes('Top') && categoryTabs.includes('Trending') && categoryTabs.includes('Watchlist') &&
    categoryTabs.includes('Prediction Markets') && categoryTabs.includes('Most Visited') && categoryTabs.includes('New'),
    `Tabs: ${categoryTabs.join(', ')}`);

  await page.click('.category-tab[data-cat="trending"]');
  await page.waitForTimeout(300);
  const trendingRowCount = await page.$$eval('#cryptoBody tr', rows => rows.length);
  log('Trending filter changes rows', trendingRowCount !== restoredRowCount,
    `Top: ${restoredRowCount}, Trending: ${trendingRowCount}`);
  await page.click('.category-tab[data-cat="top"]');
  await page.waitForTimeout(300);

  // 6. Crypto table
  console.log('\n=== CRYPTO TABLE ===');
  const tableRows = await page.$$eval('#cryptoBody tr', rows => rows.length);
  log('100+ data rows (incl index)', tableRows >= 100, `Row count: ${tableRows}`);

  // Get row texts
  const rowTexts = await page.$$eval('#cryptoBody tr', els => els.map(el => el.textContent));

  // Index row
  const indexRow = rowTexts[0];
  log('Index row: CoinTracker 20 Index', indexRow.includes('CoinTracker 20 Index'), `Found`);
  log('Index row: $154.29', indexRow.includes('154.29'), `Found`);
  log('Index row: +0.21%', indexRow.includes('+0.21%'), `Found`);
  log('Index row: +1.15%', indexRow.includes('+1.15%'), `Found`);
  log('Index row: +4.97%', indexRow.includes('+4.97%'), `Found`);

  // Bitcoin should be first data row (row 1)
  const btcRow = rowTexts[1];
  log('Bitcoin #1 present', btcRow.includes('BTC'), `Row text sample: ${btcRow.substring(0, 80)}`);
  log('Bitcoin price $75,612.78', btcRow.includes('75,612.78'), `Found: ${btcRow.includes('75,612.78')}`);
  log('Bitcoin mcap $1.51T', btcRow.includes('1.51T'), `Found: ${btcRow.includes('1.51T')}`);
  log('Bitcoin vol $42.82B', btcRow.includes('42.82B'), `Found: ${btcRow.includes('42.82B')}`);
  log('Bitcoin supply 20.01M BTC', btcRow.includes('20.01M'), `Found: ${btcRow.includes('20.01M')}`);

  // Ethereum should be row 2
  const ethRow = rowTexts[2];
  log('Ethereum #2 present', ethRow.includes('ETH'), `Row text sample: ${ethRow.substring(0, 80)}`);
  log('Ethereum price $2,356.00', ethRow.includes('2,356.00'), `Found: ${ethRow.includes('2,356.00')}`);
  log('Ethereum mcap $284.35B', ethRow.includes('284.35B'), `Found: ${ethRow.includes('284.35B')}`);

  // Solana - find it
  const solRowIndex = rowTexts.findIndex(r => r.includes('SOL'));
  log('Solana row exists', solRowIndex >= 0, `Row index: ${solRowIndex}`);
  if (solRowIndex >= 0) {
    const solRow = rowTexts[solRowIndex];
    log('Solana price $88.25', solRow.includes('88.25'), `Found: ${solRow.includes('88.25')}`);
    log('Solana mcap $50.77B', solRow.includes('50.77B'), `Found: ${solRow.includes('50.77B')}`);
  }

  // XRP
  const xrpRowIndex = rowTexts.findIndex(r => r.includes('XRP'));
  log('XRP row exists', xrpRowIndex >= 0, `Row index: ${xrpRowIndex}`);
  if (xrpRowIndex >= 0) {
    const xrpRow = rowTexts[xrpRowIndex];
    log('XRP price $1.44', xrpRow.includes('$1.44'), `Found: ${xrpRow.includes('$1.44')}`);
    log('XRP mcap $89.13B', xrpRow.includes('89.13B'), `Found: ${xrpRow.includes('89.13B')}`);
  }

  // Tether
  const tetherRowIndex = rowTexts.findIndex(r => r.includes('USDT'));
  log('USDT row exists', tetherRowIndex >= 0, `Row index: ${tetherRowIndex}`);

  // BNB
  const bnbRowIndex = rowTexts.findIndex(r => r.includes('BNB'));
  log('BNB row exists', bnbRowIndex >= 0, `Row index: ${bnbRowIndex}`);

  // Formatting checks
  const greenCount = await page.$$eval('#cryptoBody .text-green', els => els.length);
  const sparklineCount = await page.$$eval('#cryptoBody .sparkline svg', els => els.length);
  const rightAligned = await page.$$eval('#cryptoBody td.text-right', els => els.length);
  log('Green percentage cells', greenCount > 0, `Count: ${greenCount}`);
  log('Sparkline SVGs', sparklineCount > 0, `Count: ${sparklineCount}`);
  log('Right-aligned cells', rightAligned > 0, `Count: ${rightAligned}`);
  log('Tabular numerals', await page.$eval('.font-mono', el => getComputedStyle(el).fontVariantNumeric), 'Checked');

  // 7. Pagination
  console.log('\n=== PAGINATION ===');
  const paginationText = await page.textContent('.pagination');
  log('Pagination shows pages', paginationText.includes('84'), `Content includes page 84`);
  await page.click('.page-btn:nth-child(2)');
  await page.waitForTimeout(300);
  const page2Active = await page.$eval('.page-btn:nth-child(2)', el => el.classList.contains('active'));
  log('Page 2 clickable and active', page2Active, `Active: ${page2Active}`);
  await page.click('.page-btn:first-child');

  // 8. Columns toggle
  console.log('\n=== COLUMNS TOGGLE ===');
  await page.click('#btnColumns');
  await page.waitForTimeout(300);
  const columnsPanelVisible = await page.$eval('#columnsPanel', el => el.classList.contains('open'));
  log('Columns panel opens', columnsPanelVisible, `Open: ${columnsPanelVisible}`);
  await page.click('#columnsPanel input[data-col="1h"]');
  await page.waitForTimeout(300);
  const col1hHidden = await page.evaluate(() => {
    const ths = document.querySelectorAll('.crypto-table th');
    return ths[3] ? ths[3].style.display === 'none' : false;
  });
  log('Unchecking 1h hides column', col1hHidden, `Hidden: ${col1hHidden}`);
  await page.click('#columnsPanel input[data-col="1h"]');
  await page.click('#btnColumns');
  await page.waitForTimeout(200);

  // 9. Filters panel
  console.log('\n=== FILTERS PANEL ===');
  await page.click('#btnFilters');
  await page.waitForTimeout(300);
  const filterPanelVisible = await page.$eval('#filterPanel', el => el.classList.contains('open'));
  log('Filters panel opens', filterPanelVisible, `Open: ${filterPanelVisible}`);
  const filterInputs = await page.$$('.filter-input');
  log('Filter inputs exist', filterInputs.length >= 4, `Count: ${filterInputs.length}`);
  await page.click('#btnFilters');

  // 10. Market summary
  console.log('\n=== MARKET SUMMARY ===');
  const marketSummary = await page.textContent('.market-summary');
  log('$2.56T market cap', marketSummary.includes('$2.56T'), `Found`);
  log('1.47% increase', marketSummary.includes('1.47%'), `Found`);
  log('$156.9B volume', marketSummary.includes('$156.9B'), `Found`);
  log('14.51% increase', marketSummary.includes('14.51%'), `Found`);
  log('59.04% Bitcoin dominance', marketSummary.includes('59.04%'), `Found`);

  const extraBefore = await page.$eval('#marketSummaryExtra', el => el.classList.contains('open'));
  log('Extra hidden initially', !extraBefore, `Open: ${extraBefore}`);
  await page.click('#readMoreBtn');
  await page.waitForTimeout(300);
  const extraAfter = await page.$eval('#marketSummaryExtra', el => el.classList.contains('open'));
  log('Extra visible after click', extraAfter, `Open: ${extraAfter}`);
  const btnText = await page.$eval('#readMoreBtn', el => el.textContent);
  log('Button text changes', btnText.includes('Show Less'), `Text: ${btnText}`);
  await page.click('#readMoreBtn');

  // 11. Footer
  console.log('\n=== FOOTER ===');
  const footer = await page.textContent('.footer');
  log('Products section', footer.includes('Cryptocurrencies') && footer.includes('Exchanges'), `Found`);
  log('Company section', footer.includes('Terms of Use') && footer.includes('Privacy Policy'), `Found`);
  log('Support section', footer.includes('FAQ') && footer.includes('API Documentation'), `Found`);
  log('Community section', footer.includes('Twitter') && footer.includes('Discord'), `Found`);
  log('Copyright', footer.includes('2025 CoinTracker Pro'), `Found`);

  // Screenshots
  await page.screenshot({ path: '/tmp/cointracker_top.png', fullPage: false });
  await page.evaluate(() => document.querySelector('.table-wrap').scrollIntoView());
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/cointracker_table.png', fullPage: false });
  await page.screenshot({ path: '/tmp/cointracker_fullpage.png', fullPage: true });

  // Summary
  const passed = results.filter(r => r.pass).length;
  const failed = results.filter(r => !r.pass).length;
  console.log(`\n=== SUMMARY: ${passed} passed, ${failed} failed ===`);
  if (failed > 0) {
    console.log('\nFailed checks:');
    results.filter(r => !r.pass).forEach(r => console.log(`  ❌ ${r.step}: ${r.detail}`));
  }

  await browser.close();
})();

